A.dBr=d=>{const D=S.ui.D;if(!D.tag||Object.values(BRAND).includes(D.tag)||/^(더숲|노원문고) /.test(D.tag))D.tag=D.kind==='list'?BRN(d.k):TAGN(d.k);D.br=d.k;render()};
