/* 새롭게: 느낌 · 색 · 글 배치를 통째로 바꾼다. 「되돌리기」로 돌아갈 수 있다 */
const PFAM=[[0,3,6,7],[1,4,5],[2]],BFAM=[[1,2,3,5,6],[0,4,7]],SREL={moon:['star','candle'],rain:['wave','leaf'],snow:['star','candle'],cup:['candle','book'],leaf:['drop','sun'],pencil:['book','star'],star:['moon','candle'],sun:['leaf','walk'],walk:['sun','leaf'],candle:['moon','cup'],book:['pencil','cup'],house:['cup','candle'],wave:['rain','drop'],drop:['leaf','sun']};
A.dFresh=d=>{const D=S.ui.D,H=S.ui.dH=S.ui.dH||[],near=(d&&d.m)==='near';H.push(JSON.stringify(D));if(H.length>20)H.shift();const rnd=a=>a[Math.floor(Math.random()*a.length)],pick=(n,cur)=>{let v;do{v=Math.floor(Math.random()*n)}while(n>1&&v===cur);return v},k=D.kind,fam=(F,p)=>F.find(g=>g.includes(p))||F[0],
    palNear=(F,p)=>{const g=fam(F,p).filter(x=>x!==p);return g.length?rnd(g):p},palFar=(F,p)=>rnd(F.filter(g=>!g.includes(p)).flat()),symNear=()=>{const r=SREL[D.sym];if(r){D.sym=rnd(r);D.syms=[];return true}return false},say=t=>S.ui.dlog.push({t});
  if(k==='pop'){if(!D.o)D.o={head:D.head,body:D.body};const o=D.o,t=o.head.replace(/\n/g,' '),sents=(o.body||'').split(/(?<=[.!?。])\s+/).filter(Boolean);
    if(near){D.nz=((D.nz|0)+1)%3;const did=[];if(D.nz!==2){const p=palNear(PFAM,D.pal);if(p!==D.pal){D.pal=p;did.push(`색 「${POPC[p].n}」`)}}if(D.nz!==0&&symNear())did.push('그림');if(D.nz===2||!did.length){D.hs=(D.hs||1)>1?.9:1.1;did.push((D.hs>1?'제목 크게':'제목 작게'))}say(`비슷하게: 느낌 「${STY[D.st|0]}」 그대로 · ${did.join(' · ')}`)}
    else{D.st=pick(STY.length,D.st|0);D.pal=palFar(PFAM,D.pal);D.hs=1;D.tv=((D.tv|0)+1)%3;if(D.tv===1&&sents.length){D.head=sents[0].replace(/[.。]$/,'');D.body=[t.replace(/[,.]\s*$/,'')+'.',...sents.slice(1)].join(' ')}else if(D.tv===2&&sents.length>1){D.head=o.head;D.body=sents[sents.length-1]}else{D.head=o.head;D.body=o.body}if(Math.random()<.5)symNear();say(`다르게: 느낌 「${STY[D.st]}」 · 색 「${POPC[D.pal].n}」${D.tv?' · 글 배치 바꿈':''}`)}}
  else if(k==='sign'){if(near){D.pal=palNear(PFAM,D.pal);say(`비슷하게: 모양 그대로 · 색 「${POPC[D.pal].n}」`)}else{D.cv=((D.cv|0)+1)%2;D.pal=palFar(PFAM,D.pal);say(`다르게: ${['밝은 바탕','짙은 바탕'][D.cv]} · 색 「${POPC[D.pal].n}」`)}}
  else if(k==='rent'){if(near){D.pal=palNear(PFAM,D.pal);if(D.cv===1)D.pick=((D.pick|0)+1)%Math.max(1,(D.list||'').split('\n').filter(x=>x.trim()).length);say(`비슷하게: 모양 그대로 · 색 「${POPC[D.pal].n}」${D.cv===1?' · 다음 공간':''}`)}else{D.cv=((D.cv|0)+1)%3;D.pal=palFar(PFAM,D.pal);say(`다르게: ${['공간 목록','공간 하나 크게','짙은 바탕 목록'][D.cv]} · 색 「${POPC[D.pal].n}」`)}}
  else if(k==='card'){if(near){const p=palNear(PFAM,D.pal);D.pal=p;say(`비슷하게: 모양 그대로 · 색 「${POPC[p].n}」`)}else{D.cv=((D.cv|0)+1)%5;D.pal=palFar(PFAM,D.pal);say(`다르게: ${['기본','짙은 바탕','큰 번호','세로 띠','도서카드'][D.cv]} · 색 「${POPC[D.pal].n}」`)}}
  else if(k==='band'){if(near){D.pal=palNear(BFAM,D.pal);D.pals=[];say('비슷하게: 띠지 색만 가까운 색으로')}else{D.bv=((D.bv|0)+1)%3;D.pal=palFar(BFAM,D.pal);D.pals=[];const m=MOTIF.filter(x=>x[0]!=='none');D.sym=rnd(m)[0];D.syms=[];say('다르게: 띠지 색과 그림을 바꿨습니다')}}
  else if(k==='shelf'){D.pal=near?palNear(PFAM,D.pal):palFar(PFAM,D.pal);say(`${near?'비슷하게':'다르게'}: 색 「${POPC[D.pal].n}」`)}
  else{if(near&&symNear())say('비슷하게: 그림을 어울리는 것으로');else{const m=MOTIF.filter(x=>x[0]!=='none');D.sym=rnd(m)[0];say('그림을 바꿨습니다')}}
  render()};

/* 아카데미: 바로 만들기 */
A.akaTpl=d=>{const H=S.ui.dH=S.ui.dH||[];if(S.ui.D)H.push(JSON.stringify(S.ui.D));if(d.t==='ev'){const e=S.db.events.find(x=>x.id===d.id);if(!e)return;const D=Object.assign(defD(),{kind:'pop',br:'aka',tag:'아카데미하우스',st:(e.kind==='영화')?1:0,pal:(e.kind==='영화')?2:1,sym:e.kind==='영화'?'star':e.kind==='북토크'||e.kind==='책모임'?'book':'leaf',head:e.title,body:[mdw(e.date)+(e.time?' '+e.time:''),e.place,(e.memo||'').split('\n')[0]].filter(Boolean).join(' · '),badge:e.cap?`선착순 ${e.cap}명`:''});S.ui.D=D}
  else if(SIGN[d.t]){const D=Object.assign(defD(),{kind:'sign',sg:d.t,br:'aka',tag:'',cv:0},SIGN[d.t].d);if(d.t==='board'){D.body=mdw(TODAY);const L=S.db.events.filter(e=>e.date===TODAY).sort((a,b)=>(a.time||'')<(b.time||'')?-1:1);if(L.length)D.list=L.map(e=>`${e.time||''} | ${e.title} | ${e.place||''}`).join('\n')}S.ui.D=D}
  else S.ui.D=Object.assign(defD(),RENT0,{br:'aka',tag:'',cv:d.t==='space'?1:0,pick:d.t==='space'?1:0});S.ui.dlog=[];render()};
A.sgSpace=d=>{const D=S.ui.D;D.head=d.n;D.no=d.no;D.body=(d.d||'').split('·').slice(0,2).map(x=>x.trim()).join(' · ');render()};A.sgNoti=d=>{S.ui.D.head=d.t;S.ui.D.sym=d.s;render()};
A.sgToday=()=>{const L=S.db.events.filter(e=>e.date===TODAY).sort((a,b)=>(a.time||'')<(b.time||'')?-1:1);if(!L.length){toast('오늘 날짜로 잡힌 일정이 없습니다');return}S.ui.D.list=L.map(e=>`${e.time||''} | ${e.title} | ${e.place||''}`).join('\n');S.ui.D.body=mdw(TODAY);render()};
A.sgEv=d=>{const e=S.db.events.find(x=>x.id===d.id);if(!e)return;const D=S.ui.D;D.head=e.title;D.list=[e.place?`장소 | ${e.place}`:'',`시간 | ${mdw(e.date)}${e.time?' '+e.time:''}`,D.tel?'':'문의 | 02-904-0206'].filter(Boolean).join('\n');render()};

const AKT=[['차분하게',0,1],['짙게',1,1],['따뜻하게',0,3],['먹빛으로',0,5],['밤처럼',1,2]];
A.akaTone=d=>{const D=S.ui.D,t=AKT[+d.i];if(!D)return;if(D.kind==='rent'){D.cv=t[1]?2:((D.cv|0)===1?1:0)}else if(D.kind==='sign')D.cv=t[1];else D.st=t[1];D.pal=t[2];render()};
